-- Function: public.fn_find_classroom_conflicts
-- Backup generated on 2026-11-11 09:04:35

CREATE OR REPLACE FUNCTION public.fn_find_classroom_conflicts(p_tenant_id uuid, p_classroom_id uuid, p_date date, p_start time without time zone, p_end time without time zone, p_exclude_event_id uuid DEFAULT NULL::uuid)  RETURNS TABLE(event_id uuid, title character varying, start_time time without time zone, end_time time without time zone, organizer_id uuid, organizer_name text)  LANGUAGE sql  STABLE AS $function$     SELECT e.id, e.title, e.start_time, e.end_time, e.organizer_id,            COALESCE(NULLIF(TRIM(COALESCE(u.first_name,'') || ' ' || COALESCE(u.last_name,'')), ''), u.email)::text     FROM events e     JOIN event_classrooms ec ON ec.event_id = e.id     LEFT JOIN users u ON u.id = e.organizer_id     WHERE e.tenant_id = p_tenant_id       AND ec.classroom_id = p_classroom_id       AND e.event_date = p_date       AND e.status <> 'Cancelled'       AND (p_exclude_event_id IS NULL OR e.id <> p_exclude_event_id)       AND COALESCE(e.start_time, '00:00'::time) < COALESCE(p_end, '23:59:59.999999'::time)       AND COALESCE(e.end_time, '23:59:59.999999'::time) > COALESCE(p_start, '00:00'::time)     ORDER BY e.start_time NULLS FIRST; $function$ ;
